window.__votdWeek && window.__votdWeek({"week":"2029-07-30","reading":"Doctrine and Covenants 84","days":[{"d":"2029-07-30","ref":"D&C 84:5","b":"D&C","c":84,"v":5,"he":"כִּי אָמֵן הַדּוֹר הַזֶּה לֹא כֻלּוֹ יַעֲבֹר עַד אֲשֶׁר בַּיִת יִבָּנֶה לַיהוָה וְעָנָן יָנוּחַ עָלָיו אֲשֶׁר הֶעָנָן יִהְיֶה גַּם כְּבוֹד יְהוָה אֲשֶׁר יְמַלֵּא אֶת־הַבָּיִת׃","en":"For verily this generation shall not all pass away until an house shall be built unto the Lord, and a cloud shall rest upon it, which cloud shall be even the glory of the Lord, which shall fill the house."},{"d":"2029-07-31","ref":"D&C 84:20","b":"D&C","c":84,"v":20,"he":"לָכֵן בְּחֻקּוֹתֶיהָ כֹּחַ הַחֲסִידוּת נִגְלֶה׃","en":"Therefore, in the ordinances thereof, the power of godliness is manifest."},{"d":"2029-08-01","ref":"D&C 84:22","b":"D&C","c":84,"v":22,"he":"כִּי בְּלִי זֹאת אֵין אָדָם יָכוֹל לִרְאוֹת פְּנֵי אֱלֹהִים גַּם הָאָב וָחָי׃","en":"For without this no man can see the face of God, even the Father, and live."},{"d":"2029-08-02","ref":"D&C 84:23","b":"D&C","c":84,"v":23,"he":"וְאֶת זֹאת מֹשֶׁה לִמֵּד בַּאֵר הֵיטֵב לִבְנֵי יִשְׂרָאֵל בַּמִּדְבָּר וּבִקֵּשׁ בְּשָׁקְדוֹ לְקַדֵּשׁ אֶת־עַמּוֹ לְמַעַן יוּכְלוּ לִרְאוֹת פְּנֵי אֱלֹהִים׃","en":"Now this Moses plainly taught to the children of Israel in the wilderness, and sought diligently to sanctify his people that they might behold the face of God;"},{"d":"2029-08-03","ref":"D&C 84:38","b":"D&C","c":84,"v":38,"he":"וְהַמְקַבֵּל אֶת־אָבִי מְקַבֵּל אֶת־מַלְכוּת אָבִי לָכֵן כֹּל אֲשֶׁר לְאָבִי יִנָּתֵן לוֹ׃","en":"And he that receiveth my Father receiveth my Father's kingdom; therefore all that my Father hath shall be given unto him."},{"d":"2029-08-04","ref":"D&C 84:45","b":"D&C","c":84,"v":45,"he":"כִּי דְבַר יְהוָה אֱמֶת וְכׇל אֲשֶׁר אֱמֶת הוּא אוֹר וְכׇל אֲשֶׁר אוֹר הוּא רוּחַ גַּם רוּחַ יֵשׁוּעַ הַמָּשִׁיחַ׃","en":"For the word of the Lord is truth, and whatsoever is truth is light, and whatsoever is light is Spirit, even the Spirit of Jesus Christ."},{"d":"2029-08-05","ref":"D&C 84:85","b":"D&C","c":84,"v":85,"he":"וְאַל תַּחְשְׁבוּ מֵרֹאשׁ מַה תֹּאמְרוּ אַךְ אִצְרוּ בְּדַעְתְּכֶם תָּמִיד אֶת־דִּבְרֵי הַחַיִּים וְיִנָּתֵן לָכֶם בַּשָּׁעָה הַהִיא הַחֵלֶק אֲשֶׁר יִמָּדֵד לְכׇל אִישׁ׃","en":"Neither take ye thought beforehand what ye shall say; but treasure up in your minds continually the words of life, and it shall be given you in the very hour that portion that shall be meted unto every man."}]});
